import 'package:flutter/material.dart';
import '../../core/database/app_database.dart';
class LoansPage extends StatefulWidget{const LoansPage({super.key});@override State<LoansPage> createState()=>_LoansPageState();}
class _LoansPageState extends State<LoansPage>{List<Map<String,Object?>> rows=const[];bool loading=true;
 Future<void> load()async{final db=await AppDatabase.instance.database;final x=await db.rawQuery('SELECT l.*,c.name customer_name FROM customer_loans l JOIN customers c ON c.id=l.customer_id ORDER BY l.created_at DESC');if(mounted)setState((){rows=x;loading=false;});}
 @override void initState(){super.initState();load();}
 Future<void> add()async{final db=await AppDatabase.instance.database;final cs=await db.query('customers',orderBy:'name');if(cs.isEmpty)return;String cid=cs.first['id'].toString(),type='loan';final amount=TextEditingController(),note=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(context)=>StatefulBuilder(builder:(context,setLocal)=>AlertDialog(title:const Text('Customer Loan / Payment'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(initialValue:cid,items:cs.map((x)=>DropdownMenuItem(value:x['id'].toString(),child:Text(x['name'].toString()))).toList(),onChanged:(v)=>setLocal(()=>cid=v!)),const SizedBox(height:8),DropdownButtonFormField<String>(initialValue:type,items:const[DropdownMenuItem(value:'loan',child:Text('Loan / Give credit')),DropdownMenuItem(value:'payment',child:Text('Payment received'))],onChanged:(v)=>setLocal(()=>type=v!)),const SizedBox(height:8),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Amount')),const SizedBox(height:8),TextField(controller:note,decoration:const InputDecoration(labelText:'Note'))]),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Save'))])));if(ok!=true)return;await AppDatabase.instance.saveCustomerLoan(id:DateTime.now().microsecondsSinceEpoch.toString(),customerId:cid,amount:double.tryParse(amount.text)??0,type:type,note:note.text);await load();}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Customer Loans')),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add),label:const Text('Add')),body:loading?const Center(child:CircularProgressIndicator()):rows.isEmpty?const Center(child:Text('No loan transactions.')):ListView.separated(itemCount:rows.length,separatorBuilder:(_,__)=>const Divider(height:1),itemBuilder:(_,i){final x=rows[i];return ListTile(title:Text(x['customer_name'].toString()),subtitle:Text((x['type']??'').toString()+' • '+(x['note']??'').toString()),trailing:Text(x['amount'].toString()));}));}
